def listar_problemas():
    return list(PROBLEMAS_ABERTOS_ETAPA_48)

def obter_problema(numero):
    for item in PROBLEMAS_ABERTOS_ETAPA_48:
        if item['numero'] == numero:
            return dict(item)
    raise KeyError(numero)

def validar_item(item):
    obrigatorios = ['id','numero','bloco','titulo','estado','resposta','plano_investigacao','aula_direta','aula_detalhada','aula_passo_a_passo','teste']
    faltas = [c for c in obrigatorios if c not in item or not item[c]]
    if faltas:
        return False, 'faltas: ' + ', '.join(faltas)
    texto = ' '.join(str(item.get(c,'')) for c in obrigatorios).lower()
    proibidos = ['import math', 'import numpy', 'import sympy', 'import scipy', 'import sklearn', 'import torch', 'import tensorflow', 'requests.get', 'api externa como fonte']
    achados = [p for p in proibidos if p in texto]
    if achados:
        return False, 'dependencia proibida: ' + ', '.join(achados)
    if 'prova concluída' in texto or 'resolvido definitivamente' in texto:
        return False, 'promessa falsa de solução detectada'
    return True, 'OK'

def cobertura_total():
    rel = []
    completos = 0
    for item in PROBLEMAS_ABERTOS_ETAPA_48:
        ok, motivo = validar_item(item)
        rel.append((item['id'], ok, motivo))
        if ok:
            completos += 1
    return {'total': len(PROBLEMAS_ABERTOS_ETAPA_48), 'completos': completos, 'relatorio': rel}

def resumo_por_bloco():
    r = {}
    for item in PROBLEMAS_ABERTOS_ETAPA_48:
        r[item['bloco']] = r.get(item['bloco'], 0) + 1
    return r

def responder(numero, modo='normal'):
    item = obter_problema(numero)
    if modo == 'pronta':
        return item['estado']
    if modo == 'curta':
        return item['resposta']
    if modo == 'normal':
        return item['resposta'] + '\nPlano: ' + '; '.join(item['plano_investigacao'])
    if modo == 'linha':
        return item['resposta'] + '\n' + item['aula_passo_a_passo']
    return item['resposta']
